# ============================================================
# chow_test.R  —  ONE standardised regression-based Chow test
# for the breakpoint analyses in "Who Killed British Democracy?"
#
# Canonical test (matches 04_executive_instability.R / 01_pm_turnover.R):
#   A Quandt-Andrews sup-F / Chow F-sweep on a LINEAR-TREND regression.
#   For each candidate break index k, fit
#         y = a1 + b1*t   on observations 1..k
#         y = a2 + b2*t   on observations (k+1)..n
#   and compare the pooled RSS with the split RSS:
#         F(k) = ((RSS_pool - RSS_split) / p) / (RSS_split / (n - 2p))
#   with p = 2 (both intercept AND slope may break).
#   Sweep k across the interior (default 15% trim each end), the PEAK F is
#   the data-preferred turning point. Significance comes from a
#   permutation max-F null (default 10,000 draws): shuffle y, recompute the
#   whole sweep, take its max; perm_p = Pr(perm max-F >= observed peak F).
#
# This is the *regression-based* Chow (df1 = 2), NOT the mean-shift Chow
# (df1 = 1) that some older harnesses used. It tests for a change in
# LEVEL and/or TREND, which is the right test for a time-ordered series.
#
# Usage:
#   source("chow_test.R")
#   res <- chow_sweep(year = d$year, y = d$value)     # trim=.15, nperm=1e4, seed=42
#   chow_panel_figure(res, series_label = "My series",
#                     y_label = "value", outfile = "figures/my_series.png")
#
# Author: standardisation pass, 2026-07-19. WRITE ONLY to chow_standardized/.
# ============================================================

# ---- fast residual SS of a simple linear regression y ~ t -------------
# Closed form: RSS = Syy - Sxy^2 / Sxx. Identical to sum(resid(lm(y~t))^2)
# but ~100x faster (matters inside the 10,000-draw permutation loop).
.rss_lin <- function(y, t) {
  n <- length(y)
  if (n < 2) return(0)
  my <- sum(y) / n; mt <- sum(t) / n
  dt <- t - mt; dy <- y - my
  Sxx <- sum(dt * dt)
  if (Sxx <= 0) return(sum(dy * dy))        # no variation in t
  Sxy <- sum(dt * dy); Syy <- sum(dy * dy)
  Syy - Sxy * Sxy / Sxx
}

# ---- core F at one candidate break ------------------------------------
# y : numeric vector (time-ordered, NA already removed)
# t : numeric time index (usually 1..n)
# k : split point; segment 1 = 1..k, segment 2 = (k+1)..n
# min_seg : minimum observations per segment (>=3 so each side has residual df)
.chow_F_reg <- function(y, t, k, min_seg = 3) {
  n <- length(y)
  if (k < min_seg || k > n - min_seg) return(NA_real_)
  rss_pool  <- .rss_lin(y, t)
  rss_split <- .rss_lin(y[1:k], t[1:k]) + .rss_lin(y[(k+1):n], t[(k+1):n])
  if (rss_split <= 0) return(NA_real_)
  p <- 2L                                   # intercept + slope
  ((rss_pool - rss_split) / p) / (rss_split / (n - 2 * p))
}

# ---- the standardised sweep -------------------------------------------
# year : label vector aligned with y (calendar year, or PM start year, etc.)
# y    : numeric series (NAs are dropped, with `year`, before the sweep)
# trim : interior trim fraction per end (0.15 = classic Quandt-Andrews 15%)
# nperm: permutation draws for the max-F null
# seed : RNG seed (default 42, matching the exec-instability figure)
# min_seg : min obs per segment (>=3)
#
# Returns a list:
#   curve      data.frame(k, year, F)  — the full F-sweep over the interior
#   peak_year  year at the peak F
#   peak_k     index at the peak F
#   peak_F     the peak (sup) F statistic
#   crit_5pct  F(2, n-4) 5% critical value (pointwise; sup-F sig uses perm_p)
#   perm_p     permutation max-F p-value
#   significant  peak_F > crit_5pct (pointwise) — see perm_p for the honest test
#   slope_before / slope_after  linear-trend slopes each side of the peak
#   n, trim, nperm, seed
chow_sweep <- function(year, y, trim = 0.15, nperm = 10000, seed = 42,
                       min_seg = 3) {
  stopifnot(length(year) == length(y))
  ok   <- !is.na(y) & !is.na(year)
  year <- year[ok]; y <- y[ok]
  ord  <- order(year)
  year <- year[ord]; y <- y[ord]
  n <- length(y)
  t <- seq_len(n)

  # interior candidate set: 15% trim, but never fewer than min_seg per side
  lo <- max(min_seg, floor(trim * n))
  hi <- min(n - min_seg, n - floor(trim * n))
  if (hi < lo) stop(sprintf("Series too short for trim=%.2f (n=%d).", trim, n))
  ks <- lo:hi

  fstats <- vapply(ks, function(k) .chow_F_reg(y, t, k, min_seg), numeric(1))
  curve <- data.frame(k = ks, year = year[ks], F = fstats)
  curve <- curve[!is.na(curve$F), , drop = FALSE]
  if (!nrow(curve)) stop("No valid F statistics over the interior.")

  peak_i    <- which.max(curve$F)
  peak_k    <- curve$k[peak_i]
  peak_year <- curve$year[peak_i]
  peak_F    <- curve$F[peak_i]

  crit_5pct <- qf(0.95, df1 = 2, df2 = n - 4)

  # permutation max-F null (iid shuffle of y; matches exec-instability figure)
  set.seed(seed)
  perm_maxF <- replicate(nperm, {
    yp <- sample(y)
    max(vapply(ks, function(k) .chow_F_reg(yp, t, k, min_seg), numeric(1)),
        na.rm = TRUE)
  })
  perm_p <- mean(perm_maxF >= peak_F)

  # slopes either side of the preferred break (interpretive)
  m_before <- lm(y[1:peak_k]     ~ t[1:peak_k])
  m_after  <- lm(y[(peak_k+1):n] ~ t[(peak_k+1):n])

  list(curve = curve, peak_year = peak_year, peak_k = peak_k, peak_F = peak_F,
       crit_5pct = crit_5pct, perm_p = perm_p,
       significant = peak_F > crit_5pct,
       slope_before = unname(coef(m_before)[2]),
       slope_after  = unname(coef(m_after)[2]),
       n = n, trim = trim, nperm = nperm, seed = seed,
       year = year, y = y)
}

# ---- standard 2-panel figure ------------------------------------------
# Top panel : the series with a LOESS smooth + the turning-point line.
# Bottom    : the Chow F-sweep with the peak marked + 5% critical line.
# Matches the exec-instability (fig 2.6) grammar: theme_minimal, grey
# critical line, hollow peak marker, patchwork stack.
#
# res          : output of chow_sweep()
# series_label : title
# y_label      : y-axis label for the top panel
# source_note  : optional caption
# outfile      : path to save PNG (created if dir missing); NULL = return plot
chow_panel_figure <- function(res, series_label, y_label = "value",
                              source_note = NULL, outfile = NULL,
                              width = 9, height = 6, dpi = 300) {
  if (!requireNamespace("ggplot2", quietly = TRUE) ||
      !requireNamespace("patchwork", quietly = TRUE)) {
    stop("ggplot2 and patchwork are required for chow_panel_figure().")
  }
  library(ggplot2); library(patchwork)

  ser <- data.frame(year = res$year, y = res$y)
  span <- if (nrow(ser) > 25) 0.3 else 0.6

  sig_txt <- sprintf("Chow peak %s: F(2,%d) = %.2f, perm p = %.3f%s",
                     res$peak_year, res$n - 4, res$peak_F, res$perm_p,
                     if (res$peak_F > res$crit_5pct) "" else " (< 5% crit)")

  p_top <- ggplot(ser, aes(year, y)) +
    geom_line(colour = "grey55", linewidth = 0.5) +
    geom_point(colour = "grey55", size = 1) +
    geom_smooth(method = "loess", span = span, se = FALSE,
                colour = "#000000", linewidth = 1.1, formula = y ~ x) +
    geom_vline(xintercept = res$peak_year, linetype = "dashed",
               colour = "#d7191c", linewidth = 0.7) +
    annotate("text", x = res$peak_year, y = max(ser$y, na.rm = TRUE),
             label = res$peak_year, colour = "#d7191c", hjust = -0.1,
             size = 3, fontface = "bold") +
    labs(x = NULL, y = y_label) +
    theme_minimal(base_size = 10) +
    theme(panel.grid.minor = element_blank(),
          panel.grid.major.x = element_blank())

  p_bot <- ggplot(res$curve, aes(year, F)) +
    geom_hline(yintercept = res$crit_5pct, linetype = "dashed",
               colour = "#888888", linewidth = 0.5) +
    geom_line(colour = "#000000", linewidth = 0.6) +
    geom_point(data = res$curve[which.max(res$curve$F), , drop = FALSE],
               shape = 21, fill = "white", colour = "#000000",
               size = 3.5, stroke = 1.3) +
    annotate("text", x = res$peak_year, y = res$peak_F,
             label = res$peak_year, colour = "#000000", hjust = 1.25,
             size = 3, fontface = "bold") +
    annotate("text", x = min(res$curve$year), y = res$crit_5pct,
             label = "5% critical value", colour = "#888888",
             size = 2.5, hjust = 0, vjust = -0.5) +
    labs(x = NULL, y = sprintf("Chow F(2, %d)", res$n - 4)) +
    theme_minimal(base_size = 10) +
    theme(panel.grid.minor = element_blank(),
          panel.grid.major.x = element_blank())

  fig <- p_top / p_bot +
    plot_layout(heights = c(2, 1)) +
    plot_annotation(
      title = series_label,
      subtitle = sig_txt,
      caption = source_note,
      theme = theme(
        plot.title    = element_text(face = "bold", size = 11),
        plot.subtitle = element_text(size = 8.5, colour = "grey30"),
        plot.caption  = element_text(size = 7, colour = "grey40")))

  if (!is.null(outfile)) {
    dir.create(dirname(outfile), showWarnings = FALSE, recursive = TRUE)
    ggsave(outfile, fig, width = width, height = height, dpi = dpi)
  }
  invisible(fig)
}
